const tasks = [
  ["12-kprove-int-float", "kprove spec.k --definition audit-verification-kompiled --spec-module SPEC --claims SPEC.triangle-area-int-float"],
  ["13-kprove-float-int", "kprove spec.k --definition audit-verification-kompiled --spec-module SPEC --claims SPEC.triangle-area-float-int"],
  ["14-kprove-float-float", "kprove spec.k --definition audit-verification-kompiled --spec-module SPEC --claims SPEC.triangle-area-float-float"],
];
const results = await Promise.all(tasks.map(([label, command]) =>
  tools.exec_command({
    cmd: `/audit-output/evidence/run_recorded.sh ${label} /tmp/audit-work/45-triangle-area '${command}'`,
    workdir: "/audit-output",
    yield_time_ms: 30000,
    max_output_tokens: 2000,
  })
));
for (let i = 0; i < results.length; i++) {
  text(`${tasks[i][0]} wrapper_exit=${results[i].exit_code}\n${results[i].output}`);
}

const jobs = [
  ["20-supplied-integrity", "diff -ru --no-dereference /reference/reference-semantics /candidate/reference-semantics\ncmp -s /reference/prompt.py /candidate/prompt.py\ncmp -s /reference/py2mpy.py /candidate/py2mpy.py\nfind -P /candidate/reference-semantics -type l -print -quit | grep -q . && exit 1 || true"],
  ["21-generation-output-scan", "wc -l -c /generation-evidence/codex-output.log\nsha256sum /generation-evidence/codex-output.log\nrg -n '^exec$|^apply_patch$|^ succeeded|^ exited|#Top|WarnStuckClaimState|\\[Error\\]|EXPECTED FAILURE|RESULT:|tokens used' /generation-evidence/codex-output.log"],
  ["22-candidate-file-hashes", "find -P /candidate -type f -print0 | sort -z | xargs -0 sha256sum\nfind -P /candidate -type f | wc -l\nfind -P /candidate -type l -print"],
];
for (const [label, command] of jobs) {
  const result = await tools.exec_command({
    cmd: `/audit-output/evidence/run_recorded.sh ${label} /audit-output ${JSON.stringify(command)}`,
    workdir: "/audit-output",
    yield_time_ms: 30000,
    max_output_tokens: 2000,
  });
  text(`${label} wrapper_exit=${result.exit_code}\n${result.output}`);
}

